typedef struct { sqlite3_int64 id; char name[64]; double total; } order_row;

/* one operation per rule; the step loop *is* the record set */
static int orders_total_over(sqlite3 *db, double threshold, order_row *out, int *n) {
    sqlite3_stmt *st = NULL;
    if (sqlite3_prepare_v2(db, "SELECT id, name, total FROM orders WHERE total > ?", -1, &st, NULL)) return -1;
    sqlite3_bind_double(st, 1, threshold);
    while (sqlite3_step(st) == SQLITE_ROW) { /* copy columns into out[(*n)++] */ }
    sqlite3_finalize(st);
    return 0;
}
